css:
#tongsci1-3-3-2-lockkey .lk-body { grid-template-columns: 1120px minmax(0, 1fr); }
#tongsci1-3-3-2-lockkey .lk-stage { position: relative; border: 2px solid var(--ink); border-radius: 12px; overflow: hidden; background: #f3efe6; }
#tongsci1-3-3-2-lockkey .lk-stage canvas { touch-action: none; cursor: grab; user-select: none; -webkit-user-select: none; }
#tongsci1-3-3-2-lockkey .lk-panel { gap: 10px; }
#tongsci1-3-3-2-lockkey .lk-out { margin: 0; font-size: 20px; line-height: 1.5; background: #fffbe6; border: 2px solid var(--accent); border-radius: 12px; padding: 8px 14px; min-height: 6.2em; flex: none; }
#tongsci1-3-3-2-lockkey .lk-out b { color: var(--accent); }
#tongsci1-3-3-2-lockkey .lk-tab { width: 100%; border-collapse: collapse; table-layout: fixed; font: 600 16px/1.3 var(--f-body); flex: none; background: var(--paper-2); border: 2px solid var(--ink); }
#tongsci1-3-3-2-lockkey .lk-tab th { font: 700 16px/1.2 var(--f-body); background: color-mix(in srgb, var(--accent) 10%, var(--paper-2)); border: 1.5px solid var(--ink-3); padding: 5px 4px; }
#tongsci1-3-3-2-lockkey .lk-tab th:nth-child(1) { width: 34%; }
#tongsci1-3-3-2-lockkey .lk-tab th:nth-child(4) { width: 17%; }
#tongsci1-3-3-2-lockkey .lk-tab td { border: 1.5px solid var(--rule, #c9ccd3); padding: 3px 6px; height: 36px; color: var(--ink-3); text-align: center; }
#tongsci1-3-3-2-lockkey .lk-tab td:first-child { font-weight: 800; text-align: left; }
#tongsci1-3-3-2-lockkey .lk-tab tr.ok td { color: var(--ink); }
#tongsci1-3-3-2-lockkey .lk-tab tr.ok td:first-child { color: var(--good); }
#tongsci1-3-3-2-lockkey .lk-tab tr.den td:last-child { color: var(--risk); font-weight: 800; }
#tongsci1-3-3-2-lockkey .lk-quiz { flex: none; border: 2px dashed var(--ink-3); border-radius: 12px; padding: 8px 12px; font-size: 18px; line-height: 1.4; }
#tongsci1-3-3-2-lockkey .lk-quiz.done { border-style: solid; border-color: var(--good); background: var(--good-soft); }
#tongsci1-3-3-2-lockkey .lk-qh { font: 800 18px var(--f-display); color: var(--accent); margin-right: 6px; }
#tongsci1-3-3-2-lockkey .lk-qa { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; margin-top: 6px; }
#tongsci1-3-3-2-lockkey .lk-qa span { border: 2px solid var(--ink-3); border-radius: 999px; text-align: center; padding: 2px 4px; font-weight: 800; white-space: nowrap; }
#tongsci1-3-3-2-lockkey .lk-qa span.ok { border-color: var(--good); color: var(--good); background: var(--paper-2); }
#tongsci1-3-3-2-lockkey .lk-qa b { font-weight: 700; }
section#tongsci1-3-3-2-lockkey.ex.u-done .lk-tab { display: none; }

